      hClog: "Pneus bouchés : sur le dur, accélère sans RÉDUC, ça part. Ou lave-les dans un gué", hSand: "Sable : ne patine pas. Recule dans ta trace et prends de l'élan — ou dégonfle", hSandLow: "Sable : coupe RÉDUC — avec, tu ne prends pas de vitesse. Recule dans ta trace et prends de l'élan", wNone: "Rien où accrocher le treuil ici : il ne tire que vers un arbre marqué", wFar: (m) => `Treuil : approche-toi de l'arbre marqué — le câble fait ${m} m`, goAny: "Partir quand même", adNo: "La vidéo n'a pas chargé — réessaie un peu plus tard", buyGo: (p) => `Acheter ${p} et partir`, fitGo: (p) => `Monter ${p} et partir`, buyRe: (p, c) => `${p} pour ¤ ${c} — rejouer`, fitRe: (p) => `Monter ${p} — rejouer`, tNeed: (p) => `Sans ${p}, impossible de passer ici — le mécanicien t'avait prévenu. Monte-le et réessaie.`, needS: (p, n, have) => `Il faut : ${p} — ¤ ${n}, tu as ¤ ${have}.`, rentS: 'Vidéo : pièce pour un trajet', earnS: (n, g) => `◀ Commande ${n} : +¤ ${g}`, earnB: (n, g) => `◀ Gagne sur la commande ${n} : +¤ ${g}`, rentRe: (p) => `Vidéo : ${p} pour un trajet — rejouer`, tEarn: (p, n, have, k) => `Sans ${p}, impossible de passer ici : ça coûte ¤ ${n}, tu as ¤ ${have}. Refais la commande ${k}, gagne et reviens.`, tRent: (p, n, have) => `Sans ${p}, impossible de passer ici : ça coûte ¤ ${n}, tu as ¤ ${have}. Regarde une vidéo et on le monte pour un trajet.`, minC: (n) => `min. ${n}`, whyCap: (n, c) => `la commande commence à ${n}, ton camion n'en prend que ${c}`, goCap: (n) => `Il faut ${n}+`, rent: (p) => `Vidéo : ${p} pour un trajet`, hScree: "Éboulis : ne patine pas, tu t'enterres. Recule et prends de l'élan", hScreeSoft: "Éboulis : ne patine pas, tu t'enterres. Dégonfle, ou recule et prends de l'élan", hRocks: "Rochers : 4×4 et BLOC. Ça ne passe pas — recule et prends de l'élan", hStep: "Marche : recule et prends de l'élan, en 4×4", hIdle: "Se balancer sur place brûle du carburant. Recule et prends de l'élan",
